"""Close R31 as an influence diagnosis, never a GT-based deployment filter."""
import sys,json,collections,numpy as np
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'crossplatform/round31'))
from common31 import *

def main():
 ia=EXP.parent/'independent_audit';audit=read(ia/'AUDIT_RESULT.json');mass_audit=read(ia/'MASS_AUDIT_RESULT.json');assert audit['state']==mass_audit['state']=='PASS'
 ss=read(EXP/'INFLUENCE19_SUMMARY.json');mm={x['feedback_alias']:x for x in read(EXP/'LOO_VS_MASS_SUMMARY.json')};rr=read(EXP/'ALL_INFLUENCE_ROWS_PRIVATE.json');assert len(ss)==19 and len(rr)==3800
 all_zero=[x['feedback_alias'] for x in ss if all(abs(r['delta_remove_pp'])<=1e-8 for r in rr if r['feedback_alias']==x['feedback_alias'])];assert len(all_zero)==12
 def pick(alias,subset='S64'):return next(x for x in ss if x['feedback_alias']==alias)['subsets'][subset]
 d={'run':'completed','measurement':'independent_CPU_audits_PASS','claim':'correct_feedback_can_transfer_negatively;wrong_feedback_can_have_mixed_transfer;LOO_not_runtime_filter','source_reference':'R30 beta1 unchanged','trainable_module':'same fullquerymatchingMLP184960','new_Qwen_calls':0,'new_source_training_steps':0,'LOO_observations':19,'LOO_preference_count':22,'original_denominators':{'drone':10,'quad':12},'fixed_keep_n':{'drone':96,'quad':93},'removed_observations_added_to_keep':False,'main_models':23,'mass_control_models':4,'optimizer_steps':432,'influence_rows':3800,'own_platform_rows_per_model':200,'cross_platform_effect':'structuralzero; otherplatform unchanged all-state','Aothers_excludes_removed_observation':True,'no_task_IoU_change_deletions':12,'no_task_IoU_change_does_not_mean_no_parameter_or_query_change':True,'all_feedback_R30_state_reproduced_bitexact':True,'zero_feedback_source_state_bitexact':True,'W_drone012_S_same_platform_delta_pp':pick('W_drone_012')['mean_delta_remove_pp'],'W_drone012_S_balanced_system_delta_pp':pick('W_drone_012')['mean_delta_remove_pp']/2,'W_drone012_S_residual_vs_uniform_mass_pp':mm['W_drone_012']['subsets']['S64']['loo_minus_uniform_mass_pp'],'W_quad010_S_same_platform_delta_pp':pick('W_quad_010')['mean_delta_remove_pp'],'W_quad010_recovered_harm_pp_sum':pick('W_quad_010')['baseline_harms_recovered_pp_sum'],'W_quad010_lost_gain_pp_sum':pick('W_quad_010')['baseline_gains_lost_pp_sum'],'A_drone034_identity':'newwinnerblackM0 visually conflicts withwhite attribute;sourceM1 fullcaptionnotindependentgold','A_drone034_candidate_scope':'M0 comparedbutabstained;onlyM1>M5accepted;noautomaticnegative','all_R_DEV_S_labels_exposed_diagnostic_only':True,'no_new_independent_confirmation':True,'new_method_adopted':False,'next_mechanism':'conditional_scope_control_with_same_information_no_update_and_global_shrink_controls','no_feedback_blacklist_generated':True,'influence_effects_nonadditive':True}
 dump(EXP/'DECISION.json',d)
 lines=['# R31：19个反馈观测逐个移除的影响诊断','','固定R30 beta1，逐个移除19个反馈观测提供的全部偏好，并保持原189条输出保持样本、原平台偏好分母和16步更新不变。另补4个全部反馈统一缩放的名义质量对照。所有结果均为已暴露输入上的训练干预诊断，没有新独立确认，也没有据GT删标签形成部署方法。','','## 核心判断','','1. 视觉复核支持的正确反馈也可能产生负迁移。移除W_drone_012后，同平台S32均值提高3.787802pp；其同名义质量全反馈缩放对照在S上为0，不能仅用总偏好质量减少解释。','2. 已知错误W_quad_010既带来主要损害，也伴随更多任务收益。移除它救回68.605200 pp-sum既有损害，却损失151.995630 pp-sum既有收益，同平台S32净下降2.605951pp。错误标签没有因此变正确，但直接删它并不改善总体指标。','3. 多条反馈移除都能救回同一条S_quad_016，且Quad统一缩放10/12也能救回该观测；这是需要区分内容、强度与联合阈值的证据，不能将各LOO影响相加或当Shapley值。','4. A_drone_034的新组对应近景黑色轿车，和目标white属性冲突；它不是缺失候选，而是在已有比较上弃权后，没有接受关系覆盖。这个单例没有被改标为新负例。','','## 固定协议与控制','','源权重为同一Waymo-only epoch100，学生仍输入XYZ+文字。更新R30相同的184960参数query匹配MLP，冻结框和所有非匹配参数。source初始化、AdamW5e-4、16步、weight_decay0、seed0、beta1、log-odds RankNet温度0.1均不变。','','原22条伪偏好来自19个观测：8Drone、11Quad。每次移除该观测的所有偏好，原始gap向量保留，被移除项乘零，仍除以原平台分母：Drone10、Quad12。保持集合原封不动为96Drone/93Quad；移除者不加入保持项。原source q0、输出保持目标、候选分组和组内source代表都不重建。','','19次只重新优化被干预的平台；另一平台沿用未变的R30全反馈状态。因此下文S64列实际上是该平台32条、R64+S64列是该平台64条的平均效应。另一平台固定时，两平台balanced均值效应等于这里同平台效应的一半。跨平台零影响是实验结构事实，不是额外3800条跨平台新预测。','','每个平台先复现全反馈R30状态，并跑零偏好优化控制：主运行23个状态（2all+19LOO+2zero），368优化步。全反馈状态与R30 b1逐位一致，零反馈状态与source逐位一致，共享A/DEV/S336条的query和IoU完全复现。','','A208、DEV64、R64、S64合计400个观测，每个平台200个；每条LOO只保存对应平台200条，共3800条影响记录。Aothers排除被移除观测本身，并另拆其余反馈观测与原无反馈保持集合。DEV、R64、S64都已暴露，仅用于解释，不得重新称为未见确认。','','定义delta_remove=IoU_minus_a−IoU_all：正值表示去掉此反馈有益，负值表示该反馈对该观测有帮助。它是16步非线性优化下的干预结果，不是可加的标签价值。','','## 19个反馈观测的总体影响表','','单位均为mIoU百分点；S的救回/损失数是观测个数。质量残差为LOO效应减去相同名义质量的全反馈缩放效应。','','|移除的反馈观测|偏好数|A其他观测变化|R+S同平台变化|S同平台变化|S两平台balanced变化|S救回/损失|S质量匹配残差|','|---|---:|---:|---:|---:|---:|---:|---:|']
 for x in ss:
  a=x['subsets']['A208'];rs=x['subsets']['R64_S64'];s=x['subsets']['S64'];m=mm[x['feedback_alias']]['subsets']['S64'];lines.append(f"|{x['feedback_alias']}|{x['removed_preferences']}|{a['mean_delta_remove_pp']:+.6f}|{rs['mean_delta_remove_pp']:+.6f}|{s['mean_delta_remove_pp']:+.6f}|{s['mean_delta_remove_pp']/2:+.6f}|{s['improves_if_removed']}/{s['worsens_if_removed']}|{m['loo_minus_uniform_mass_pp']:+.6f}|")
 lines+=['','12/19删除在全部本平台200观测上的任务IoU均不变，不等于参数或query完全不变；例如Z_quad_008仍改变2个query，但对应IoU相同。其余7条反馈存在任务级影响。完整3800行保留，不只导出变化子集。','','值得区分的几项：','','|反馈观测|已有视觉判断范围|S原恶化子集改善和 pp-sum|S原改善子集下降和 pp-sum|S同平台净变化 pp|','|---|---|---:|---:|---:|']
 for alias,label in [('W_drone_012','视觉主体选择合理'),('W_quad_010','已知主体/参照人错绑'),('A_quad_028','视觉主体选择合理'),('Z_quad_023','视觉主体选择合理')]:
  s=pick(alias);lines.append(f"|{alias}|{label}|{s['baseline_harms_recovered_pp_sum']:.6f}|{s['baseline_gains_lost_pp_sum']:.6f}|{s['mean_delta_remove_pp']:+.6f}|")
 lines+=['','pp-sum是在相应32条观测的指定子集上累加的IoU百分点变化，不是均值或相互独立的贡献。原恶化子集的改善未按source上限截断，原改善子集的下降也未按原收益封顶，因此它们不严格等于被完全恢复或丢失的原始收益；不能横向相加构造新模型。其他未专门复核的观测身份不被强行标为正确或错误。','','## 名义偏好质量匹配控制','','移除项即使使用固定分母，也会降低偏好总项质量。因此在原LOO封存评分之后，登记4个诊断对照：全部反馈保留，整个pref乘c=(N−移除条数)/N，保持U、beta1、source、分母、16步不变。实际系数为Drone0.9/0.8和Quad11/12、10/12；没有按R/S选最优系数作为新方法。','','它只匹配名义质量，不匹配梯度范数、方向或Adam有效位移。历史输出字段active_preferences在这4个控制中表示int(sum(weights))，不是非零偏好项数；真实全部10/12项均保留。','','Drone两个质量控制在S的任务IoU均不变，因此W_drone_012的+3.787802pp仍是相对相同质量控制的残差。Quad11/12在S不变，10/12为+2.143912pp，足以救回S_quad_016；W_quad_011移除本身为0，但其2条质量控制有该收益。该差异表明不能把移除效应统一解释为“某反馈质量差”，也不能忽略总强度与联合决策阈值。完整每条LOO/质量控制残差和800条质量控制任务值均保留。','','## 请求中的两条大幅恶化观测','','S_drone_005：source IoU39.038298%，R30为0；只有移除W_drone_012在这组LOO中恢复到39.038298%。这与总体S效应一致，但不是仅为这条案例选删标签。','','S_quad_016：source IoU68.605200%，R30为0；移除A_quad_028、W_quad_010或Z_quad_023分别都恢复到68.605200%。前两者同时丢失主要收益，后者在S追回损害且未丢原收益。三次恢复是同一观测，不能累加成三份独立收益。这里只记录影响；没有按结果部署这些删除方案，也没有运行联合删除后的oracle模型。','','## A_drone_034的独立身份核查','','CPU视觉/点支撑复核不读取任务GT或IoU。Source返回q3，主要对应白色紧凑车辆M1，框内已归属前景点170/184=92.39%来自M1。R30返回q7，框内109/109个已归属前景点来自近景黑色轿车M0，0个来自M1。M0的深色与主体white属性冲突，这比仅凭低IoU判断更具体。','','但完整描述的左右/车头朝向和画面有视角或文字歧义，M1只能称外观相容，不能被认证为满足全文的独立世界身份金标。点归属依赖共享标定、可见性及预测mask，表面支撑也不代表完整框几何正确。原图、点坐标和私有元数据保留本地。','','M0并非缺席比较：原pair00比较过M1/M0，Qwen两次编号均偏物理M0，但其中一次间隔0.125<0.5，故为U而不进损失。唯一接受的是M1>M5；它不约束M1>M0。该观测因有接受反馈而不在无反馈U保持集合里。最终M0组分最高query是q17（约0.141400），组M1最高为q18（约0.116817），实际返回q7是M0组冻结source代表，不能混成同一个最高query。','','这说明此处同时存在部分关系未监督与共享更新传播。仍需以总体影响表选择下一机制；没有因为未支持的新候选就把M0加入负集合。','','## 文献依据与下一步','','独立文献审计核对原论文和官方实现，文档与直接链接附在literature目录。当前优先检验条件化传播：在有反馈支持的特征邻域使用已有R30修正，其他输入更多保留source；其启发来自[GRACE的局部编辑](https://papers.neurips.cc/paper_files/paper/2023/hash/95b6e2ff961580e03c0a662a63a71812-Abstract-Conference.html)，不称GRACE复现。','','下一轮必须保留同一键/路由/反馈预算的无参数更新直接记忆，以及同平均门质量、同实际修正范数的全局缩步对照，否则可能只是整体少更新。候选级门前需统一source q0的相对分数，避免R28式任意零点制造排序变化。精确读出与数值端点约束由下一轮另行登记，R31不新增方法或确认结果。','','PCGrad仅在梯度冲突/联合更新机制值得检验时作备选；OGD需要明确输出Jacobian、一阶保护和Adam位移的限制。论文方法都有不同标签、源训练或任务前提，不能直接把其结论搬到3EED。完整审计也说明MOS的框相似信号在冻结框任务可能退化，固定类别的TAST/LAME不能把跨场景query槽位当同一类别。','','## 审计、工程记录、成本与裁决','','独立CPU审计PASS：23个固定分母初始目标、4600个状态读出/组选择/任务分值、3800条影响和133个子集聚合重构；质量控制另核4个目标、800条任务分值、3800残差和95聚合。All状态与R30 b1逐位一致，zero与source逐位一致，原189保持集合和删除者不加入规则全部核验。审计未独立重训模型，代码/原始收据与初始目标重构共同支持训练契约；任务几何沿用既有独立CPU评估器。','','attempt001因legacy import覆盖feature读取函数，无法路由S64，在任何优化器步骤前报错；修复导入后的读取hook后使用全新attempt002，失败日志和修复说明保留，没有覆盖旧实验或改变科学配置。','','23状态×16步约14.77秒、4质量状态×16步约5.39秒，torch分配峰值约450MB；这些是缓存匹配头实验的程序计时，不含特征获取，也不是完整在线部署成本。新Qwen调用0，源模型训练0，新独立确认0。','','裁决：影响诊断支持把下一步重点放在修正的传播范围和条件化适用性，不能把剩余问题全归因于错反馈；名义质量/联合阈值效应也必须保留。R31没有改变部署反馈、没有选GT黑名单或采用新方法。全部正负影响、零效应、质量残差和身份边界保留。后续新方法应锁定后使用另留新观测，R64/S64继续只作诊断。']
 (EXP/'REPORT.md').write_text('\n'.join(lines)+'\n');dump(EXP/'RUN_STATE.json',{'run':'completed','measurement':'independent_CPU_audits_PASS','claim':d['claim'],'diagnostic_only':True,'new_method_adopted':False});dump(EXP/'FINAL_CODE_SNAPSHOT.json',{'programs':{str(p.relative_to(ROOT)):sha(p) for folder in [BASE,EXP.parent,ia,EXP.parent/'independent_identity'] for p in folder.glob('*.py')},'not_all_code_preregistered':True,'mass_control_posthoc_amendment_preserved':True});print('FINAL31',len(ss),len(rr),len(all_zero))
if __name__=='__main__':main()
